<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Golden character</title>
<style>
html,body{margin:0;width:244px;height:240px;overflow:hidden;background:#fff}
canvas{display:block;width:244px;height:240px}
</style>
</head>
<body>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.background = new THREE.Color('#ffffff');

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(244,240);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const viewHeight = 4.6;
const ref = new THREE.OrthographicCamera(
  -viewHeight*244/240/2, viewHeight*244/240/2,
  viewHeight/2, -viewHeight/2, 0.1, 60
);
ref.position.set(0,2.70,10);
ref.lookAt(0,2.24,0);

scene.add(new THREE.HemisphereLight('#fffdf2','#b9a078',1.35));
scene.add(new THREE.AmbientLight('#ffffff',0.20));

const key = new THREE.DirectionalLight('#fff7e7',3.15);
key.position.set(-3.8,7.5,5.5);
key.castShadow = true;
key.shadow.mapSize.set(1024,1024);
key.shadow.camera.left = -4;
key.shadow.camera.right = 4;
key.shadow.camera.top = 6;
key.shadow.camera.bottom = -2;
key.shadow.camera.near = 0.5;
key.shadow.camera.far = 20;
key.shadow.normalBias = 0.025;
key.shadow.bias = -0.0002;
key.shadow.radius = 4;
key.target.position.set(0,2,0);
scene.add(key,key.target);

const fill = new THREE.DirectionalLight('#ffffff',0.65);
fill.position.set(4,3,5);
scene.add(fill);
const backLight = new THREE.DirectionalLight('#fff1c6',0.8);
backLight.position.set(1,5,-5);
scene.add(backLight);

let seed = 42137;
function random() {
  seed = (Math.imul(seed,1664525)+1013904223)>>>0;
  return seed/4294967296;
}
const noiseBytes = new Uint8Array(64*64*4);
for(let i=0;i<64*64;i++){
  const v = Math.floor(115+random()*75);
  noiseBytes[i*4]=v;
  noiseBytes[i*4+1]=v;
  noiseBytes[i*4+2]=v;
  noiseBytes[i*4+3]=255;
}
const grain = new THREE.DataTexture(noiseBytes,64,64,THREE.RGBAFormat);
grain.wrapS = grain.wrapT = THREE.RepeatWrapping;
grain.repeat.set(5,5);
grain.magFilter = THREE.LinearFilter;
grain.minFilter = THREE.LinearFilter;
grain.needsUpdate = true;

function material(color, extra={}) {
  return new THREE.MeshStandardMaterial({
    color, roughness:0.94, metalness:0,
    bumpMap:grain, bumpScale:0.009, ...extra
  });
}
const bodyMaterial = material('#ffffff',{vertexColors:true});
const armMaterial = material('#ffc022');
const shoulderMaterial = material('#f6bb24');
const muzzleMaterial = material('#ffd04a');
const pawMaterial = material('#493919',{roughness:1,bumpScale:0.016});
const pawFingerMaterial = material('#4c3d1e',{roughness:1,bumpScale:0.015});
const eyeRimMaterial = material('#d2ad2c',{bumpScale:0.003});
const eyeMaterial = material('#16190b',{
  roughness:0.39,bumpMap:null,bumpScale:0
});
const glintMaterial = new THREE.MeshBasicMaterial({color:'#d7d6aa'});
const mouthMaterial = material('#b68d25',{bumpMap:null});

const character = new THREE.Group();
character.name = 'golden-plush-character';
character.position.x = 0.035;
scene.add(character);

function group(name,parent,position) {
  const result = new THREE.Group();
  result.name = name;
  if(position) result.position.copy(position);
  parent.add(result);
  return result;
}
const torso = group('torso',character);
const head = group('head',character,new THREE.Vector3(0,3.25,0));

const profile = [
  [-0.71,0.001,0.001],
  [-0.60,0.66,0.43],
  [-0.44,1.16,0.73],
  [-0.20,1.49,0.92],
  [ 0.18,1.65,1.02],
  [ 0.75,1.71,1.075],
  [ 1.25,1.67,1.04],
  [ 1.80,1.52,0.94],
  [ 2.24,1.30,0.82],
  [ 2.65,1.09,0.71],
  [ 2.95,0.88,0.64],
  [ 3.27,0.72,0.575],
  [ 3.58,0.665,0.555],
  [ 3.92,0.65,0.545],
  [ 4.22,0.61,0.50],
  [ 4.44,0.53,0.43],
  [ 4.62,0.42,0.33],
  [ 4.77,0.22,0.17],
  [ 4.83,0.001,0.001]
];

function profileValue(y,k) {
  if(y<=profile[0][0]) return profile[0][k];
  if(y>=profile[profile.length-1][0]) return profile[profile.length-1][k];
  let i=0;
  while(profile[i+1][0]<y) i++;
  const a=profile[i],b=profile[i+1];
  const previous=profile[Math.max(0,i-1)];
  const next=profile[Math.min(profile.length-1,i+2)];
  const span=b[0]-a[0], t=(y-a[0])/span;
  const m0=(b[k]-previous[k])/(b[0]-previous[0]);
  const m1=(next[k]-a[k])/(next[0]-a[0]);
  const t2=t*t,t3=t2*t;
  return Math.max(0.001,
    (2*t3-3*t2+1)*a[k]+(t3-2*t2+t)*span*m0+
    (-2*t3+3*t2)*b[k]+(t3-t2)*span*m1
  );
}
const goldLow = new THREE.Color('#efb530');
const goldHigh = new THREE.Color('#ffcf20');
const bellyLow = new THREE.Color('#edc487');
const bellyHigh = new THREE.Color('#ffe3a5');

function skinColor(x,y,front) {
  const c=goldLow.clone().lerp(goldHigh,THREE.MathUtils.smoothstep(y,0,3.8));
  const belly=bellyLow.clone().lerp(bellyHigh,THREE.MathUtils.smoothstep(y,0,2.6));
  const oval=Math.exp(-Math.pow(x/1.08,4)-Math.pow((y-1.03)/1.61,4));
  const facing=THREE.MathUtils.smoothstep(front,0.1,0.82);
  c.lerp(belly,0.94*oval*facing);
  return c;
}

function makeBodySection(name,y0,y1,offset,parent) {
  const rows=Math.ceil((y1-y0)*28);
  const sides=96;
  const positions=[],normals=[],colors=[],uvs=[],indices=[];
  for(let j=0;j<=rows;j++){
    const y=y0+(y1-y0)*j/rows;
    const r=profileValue(y,1),d=profileValue(y,2);
    const dr=(profileValue(y+0.002,1)-profileValue(y-0.002,1))/0.004;
    const dd=(profileValue(y+0.002,2)-profileValue(y-0.002,2))/0.004;
    for(let i=0;i<=sides;i++){
      const a=i/sides*Math.PI*2,s=Math.sin(a),c=Math.cos(a);
      const x=r*s,z=d*c;
      positions.push(x,y-offset,z);
      const n=new THREE.Vector3(d*s,-d*dr*s*s-r*dd*c*c,r*c).normalize();
      normals.push(n.x,n.y,n.z);
      const color=skinColor(x,y,c);
      colors.push(color.r,color.g,color.b);
      uvs.push(i/sides,(y+0.71)/5.54);
      if(j<rows && i<sides){
        const p=j*(sides+1)+i,q=p+sides+1;
        indices.push(p,p+1,q,p+1,q+1,q);
      }
    }
  }
  for(const top of [false,true]){
    const row=top?rows:0;
    const y=top?y1:y0;
    const center=positions.length/3;
    positions.push(0,y-offset,0);
    normals.push(0,top?1:-1,0);
    const c=skinColor(0,y,0);
    colors.push(c.r,c.g,c.b);
    uvs.push(0.5,0.5);
    for(let i=0;i<sides;i++){
      const a=row*(sides+1)+i;
      if(top) indices.push(center,a,a+1);
      else indices.push(center,a+1,a);
    }
  }
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geometry.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
  geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
  geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));
  geometry.setIndex(indices);
  const mesh=new THREE.Mesh(geometry,bodyMaterial);
  mesh.name=name;
  mesh.castShadow=true;
  mesh.receiveShadow=true;
  parent.add(mesh);
  return mesh;
}
makeBodySection('pear-shaped-body',-0.71,3.25,0,torso);
makeBodySection('rounded-head-and-neck',3.25,4.83,3.25,head);

const sphereGeometry = new THREE.SphereGeometry(1,40,28);
function ellipsoid(name,parent,mat,position,scale,rotation=0) {
  const mesh=new THREE.Mesh(sphereGeometry,mat);
  mesh.name=name;
  mesh.position.set(...position);
  mesh.scale.set(...scale);
  mesh.rotation.z=rotation;
  mesh.castShadow=true;
  mesh.receiveShadow=true;
  parent.add(mesh);
  return mesh;
}

const face=group('face',head);
const eyes=group('eyes',face);
function makeEye(name,x,y,z,turn) {
  const eye=group(name,eyes,new THREE.Vector3(x,y-3.25,z));
  eye.rotation.y=turn;
  eye.rotation.z=turn>0?-0.06:0.07;
  ellipsoid('soft-eye-surround',eye,eyeRimMaterial,[0,0,0],[0.108,0.148,0.055]);
  ellipsoid('black-eye',eye,eyeMaterial,[0,0.003,0.042],[0.074,0.111,0.056]);
  ellipsoid('small-catchlight',eye,glintMaterial,[-0.019,0.037,0.091],[0.015,0.022,0.008]);
}
makeEye('left-eye',-0.405,4.105,0.432,-0.48);
makeEye('right-eye',0.405,4.175,0.405,0.49);

const mouth=group('muzzle-and-mouth',face);
ellipsoid('soft-yellow-muzzle',mouth,muzzleMaterial,
  [0,3.825-3.25,0.548],[0.285,0.155,0.155]);
const noseMat=material('#dcb537',{roughness:1,bumpMap:null});
ellipsoid('small-golden-nose',mouth,noseMat,
  [-0.005,3.898-3.25,0.685],[0.052,0.030,0.019]);
const smileCurve=new THREE.CatmullRomCurve3([
  new THREE.Vector3(-0.14,3.759-3.25,0.667),
  new THREE.Vector3(-0.065,3.737-3.25,0.690),
  new THREE.Vector3(0.020,3.735-3.25,0.694),
  new THREE.Vector3(0.125,3.762-3.25,0.669)
]);
const smile=new THREE.Mesh(new THREE.TubeGeometry(smileCurve,24,0.009,6,false),mouthMaterial);
smile.name='quiet-curved-mouth';
mouth.add(smile);

const leftArm=group('left-arm',character,new THREE.Vector3(-0.98,2.72,0.02));
const leftUpper=group('left-upper-arm',leftArm);
ellipsoid('rounded-upper-arm',leftUpper,shoulderMaterial,
  [-0.17,-0.37,0.14],[0.39,0.61,0.39],-0.27);
const leftForearm=group('left-forearm',leftArm,new THREE.Vector3(-0.24,-0.80,0.46));
ellipsoid('upturned-forearm',leftForearm,armMaterial,
  [0.035,0.24,0.15],[0.415,0.655,0.395],-0.23);

const rightArm=group('right-arm',character,new THREE.Vector3(1.04,2.78,-0.025));
const rightUpper=group('right-upper-arm',rightArm);
ellipsoid('rounded-upper-arm',rightUpper,shoulderMaterial,
  [0.26,-0.25,0.08],[0.345,0.545,0.35],0.40);
const rightForearm=group('right-forearm',rightArm,new THREE.Vector3(0.59,-0.70,0.37));
ellipsoid('raised-forearm',rightForearm,armMaterial,
  [0.055,0.29,0.12],[0.315,0.625,0.34],-0.105);

function makePaw(parent,name,position,rotation,scale=1) {
  const hand=group(name,parent,new THREE.Vector3(...position));
  hand.rotation.z=rotation;
  hand.scale.set(scale,1,0.96);
  ellipsoid('rounded-palm',hand,pawMaterial,[0,-0.015,0],[0.279,0.285,0.255]);
  const fingers=group('curled-fingers',hand);
  ellipsoid('outer-finger',fingers,pawFingerMaterial,[-0.145,0.145,0.008],[0.113,0.163,0.204]);
  ellipsoid('middle-finger',fingers,pawFingerMaterial,[-0.008,0.190,0.005],[0.122,0.163,0.215]);
  ellipsoid('inner-finger',fingers,pawFingerMaterial,[0.127,0.148,0.014],[0.111,0.153,0.204]);
  ellipsoid('folded-thumb',hand,pawMaterial,[0.211,-0.075,0.091],[0.113,0.163,0.161],0.32);
  return hand;
}
makePaw(leftForearm,'left-hand',[0.20,0.90,0.385],0.34,1);
makePaw(rightForearm,'right-hand',[0.065,1.00,0.265],-0.29,0.80);

const feet=group('feet',character);
const footMaterial=material('#eeb02c');
const leftFoot=group('left-foot',feet,new THREE.Vector3(-0.72,-0.62,0.24));
const rightFoot=group('right-foot',feet,new THREE.Vector3(0.72,-0.62,0.24));
ellipsoid('left-rounded-foot',leftFoot,footMaterial,[0,0,0],[0.48,0.17,0.59],-0.10);
ellipsoid('right-rounded-foot',rightFoot,footMaterial,[0,0,0],[0.48,0.17,0.59],0.10);

const floor=new THREE.Mesh(
  new THREE.PlaneGeometry(200,200),
  new THREE.MeshBasicMaterial({color:'#ffffff'})
);
floor.name='white-ground';
floor.rotation.x=-Math.PI/2;
floor.position.y=-0.795;
scene.add(floor);

const shadowFloor=new THREE.Mesh(
  new THREE.PlaneGeometry(200,200),
  new THREE.ShadowMaterial({color:'#897e66',opacity:0.17})
);
shadowFloor.name='soft-ground-shadow';
shadowFloor.rotation.x=-Math.PI/2;
shadowFloor.position.y=-0.793;
shadowFloor.receiveShadow=true;
scene.add(shadowFloor);

function render(t) {
  renderer.setRenderTarget(null);
  renderer.setViewport(0,0,244,240);
  renderer.setScissorTest(false);
  renderer.render(scene,ref);
}
window.nwb={
  scene,
  renderer,
  cameras:{ref},
  characters:[character],
  render,
  ready:true
};
render(0);
</script>
</body>
</html>
